 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    full_colors = {row[0] for row in grid if all(v == row[0] for v in row) and row[0] != background}
    for r, row in enumerate(grid):
        colors = set(row) - {background}
        if len(colors) == 1:
            color = next(iter(colors))
            if color in full_colors:
                for c, value in enumerate(row):
                    if value == background:
                        out[r][c] = 1
    return out
